from pysat.formula import CNF
from pysat.solvers import Solver

# Define the Sudoku grid size
N = 16

# Define the block size
B = 4

# Create a CNF formula
formula = CNF()

# Add constraints for each row, column, and block
for i in range(N):
    for j in range(N):
        # Each cell must contain a value from 1 to N
        formula.append([N * N * i + N * j + k for k in range(1, N + 1)])

        # Each row must contain each value from 1 to N exactly once
        for k in range(1, N + 1):
            formula.append([-N * N * i - N * j - k for j in range(N)])
            for j2 in range(j + 1, N):
                formula.append([-N * N * i - N * j - k, -N * N * i - N * j2 - k])

        # Each column must contain each value from 1 to N exactly once
        for k in range(1, N + 1):
            formula.append([-N * N * i - N * j - k for i2 in range(N)])
            for i2 in range(i + 1, N):
                formula.append([-N * N * i - N * j - k, -N * N * i2 - N * j - k])

        # Each block must contain each value from 1 to N exactly once
        for k in range(1, N + 1):
            block_i = i // B
            block_j = j // B
            for i2 in range(block_i * B, (block_i + 1) * B):
                for j2 in range(block_j * B, (block_j + 1) * B):
                    if (i2, j2) != (i, j):
                        formula.append([-N * N * i - N * j - k, -N * N * i2 - N * j2 - k])

# Add constraints for the fixed values
fixed_values = [(5, 6), (13, 14), (14, 15), (18, 7), (22, 3), (26, 15), (27, 16), (33, 10), (34, 11), (42, 3), (53, 10), (54, 11), (57, 6), (58, 7), (69, 5), (71, 7), (80, 6), (81, 5), (83, 7), (84, 2), (85, 1), (94, 12), (103, 15), (106, 4), (107, 3), (109, 5), (112, 14), (115, 15), (120, 6), (135, 6), (136, 11), (140, 15), (141, 16), (148, 3), (150, 1), (170, 1), (175, 6), (185, 8), (188, 3), (190, 1), (196, 8), (199, 5), (201, 11), (203, 9), (208, 8), (218, 14), (240, 16), (241, 15), (243, 13), (244, 12), (253, 3)]
for i, j in fixed_values:
    formula.append([N * N * i + N * j + k for k in range(1, N + 1) if k != j + 1])

# Solve the Sudoku puzzle
solver = Solver(bootstrap_with=formula.clauses)
if solver.solve():
    model = solver.get_model()
    solution = [0] * (N * N)
    for i in range(N * N):
        for j in range(1, N + 1):
            if model[N * N * i + j - 1] > 0:
                solution[i] = j
    print(solution)
else:
    print("UNSATISFIABLE")
